L001786	\section{II. Calibration of the experiment}
L001787	
L001788	
L001789	
L001790	
L001791	\begin{figure}[b]
L001792	\includegraphics[width=1.0\linewidth]{FigSlife.pdf}
L001793	\caption{{Experiment Calibration}.
L001794	{(a)} EIT transmission spectrum. {The blue circles represent the measured EIT transmission profile of the ensemble, and the red dashed line is the fitted theoretical curve.} The measured OD with a Gaussian probe beam is 280.
